import { describe, expect, it, vi } from "vitest";
vi.mock("@/lib/db", () => ({ db: {} }));
import { buildMime } from "@/lib/gmail";
import { emailHtml } from "@/lib/email-html";

// Decode the leaf parts so assertions cover the actual wire content, including UTF-8.
function textPart(mime: string, type: string) {
  const part = mime
    .split(/\r\n--[^\r\n]+\r\n/)
    .find((part) => part.startsWith(`Content-Type: ${type};`))!;
  expect(part).toBeDefined();
  const split = part.indexOf("\r\n\r\n");
  const headers = part.slice(0, split);
  const content = part
    .slice(split + 4)
    .split(/\r\n--/)[0]
    .replace(/\r\n$/, "");
  if (headers.includes("Content-Transfer-Encoding: base64"))
    return Buffer.from(content, "base64").toString("utf8");
  if (headers.includes("Content-Transfer-Encoding: quoted-printable")) {
    return Buffer.from(
      content
        .replace(/=\r\n/g, "")
        .replace(/=([\dA-F]{2})/gi, (_, hex) =>
          String.fromCharCode(parseInt(hex, 16)),
        ),
      "latin1",
    ).toString("utf8");
  }
  return content;
}

describe("readable-width email delivery", () => {
  it.each([false, true])(
    "includes both alternatives with attachment=%s",
    async (attach) => {
      const body =
        'Hi 世界 👋\n\nFirst paragraph.\nA second line.\n\n<script>alert("x")</script> & goodbye\nhttps://example.test/work?a=1&b=2';
      const pdf = Buffer.from("%PDF-1.4\n%%EOF");
      const raw = await buildMime({
        from: "[REDACTED_EMAIL]",
        to: "[REDACTED_EMAIL]",
        subject: "Hello 世界",
        body,
        messageId: "<[REDACTED_EMAIL]>",
        ...(attach
          ? { attachment: { fileName: "resume.pdf", bytes: pdf } }
          : {}),
      });
      const mime = Buffer.from(raw, "base64url").toString();
      expect(mime).toContain("multipart/alternative");
      expect(textPart(mime, "text/plain").replace(/\r\n/g, "\n")).toBe(body);
      const html = textPart(mime, "text/html");
      expect(html.replace(/\r\n/g, "\n")).toBe(emailHtml(body));
      expect(html).toContain("Hi 世界 👋<br>");
      expect(html).toContain(
        "&lt;script&gt;alert(&quot;x&quot;)&lt;/script&gt; &amp; goodbye",
      );
      expect(html).toContain(
        '<a href="https://example.test/work?a=1&amp;b=2">',
      );
      expect(html).not.toMatch(/<pre|<script/);
      expect(html).toContain("width:100%;max-width:640px;");
      expect(html.replace(/\r\n/g, "\n")).toContain(
        "Hi 世界 👋<br>\n<br>\nFirst paragraph.<br>\nA second line.<br>\n<br>",
      );
      expect(mime.match(/^To:.*$/gm)).toEqual(["To: [REDACTED_EMAIL]"]);
      expect(mime).not.toMatch(/^(Cc|Bcc):/m);
      if (attach) {
        expect(mime).toContain("multipart/mixed");
        expect(mime).toContain("application/pdf");
        expect(mime).toContain("resume.pdf");
        expect(mime).toContain(pdf.toString("base64"));
      }
    },
  );
  it("formats bold, bullet points, and numbered lists while keeping plain text", async () => {
    const body =
      "Hi **Alex**,\n\n- **Project** <img src=x>\n* Second item\n\n3. First step\n4. Next step\n\nUnmatched ** stays literal.";
    const raw = await buildMime({
      from: "[REDACTED_EMAIL]",
      to: "[REDACTED_EMAIL]",
      subject: "Formatting",
      body,
      messageId: "<[REDACTED_EMAIL]>",
    });
    const mime = Buffer.from(raw, "base64url").toString();
    expect(textPart(mime, "text/plain").replace(/\r\n/g, "\n")).toBe(body);
    const html = textPart(mime, "text/html");
    expect(html).toContain("Hi <strong>Alex</strong>,");
    expect(html).toContain(
      "<li><strong>Project</strong> &lt;img src=x&gt;</li><li>Second item</li>",
    );
    expect(html).toContain('<ol start="3"');
    expect(html).toContain("<li>First step</li><li>Next step</li>");
    expect(html).toContain("Unmatched ** stays literal.");
  });
  it("preserves every authored line break and escapes link attributes", () => {
    expect(emailHtml("a\r\n\r\nb\rc\n")).toContain(
      "a<br>\n<br>\nb<br>\nc<br>\n",
    );
    const html = emailHtml(
      'HTTP://example.test/a_(b). https://example.test/" onclick="bad javascript:alert(1)',
    );
    expect(html).toContain(
      '<a href="HTTP://example.test/a_(b)">HTTP://example.test/a_(b)</a>.',
    );
    expect(html).toContain(
      '<a href="https://example.test/">https://example.test/</a>&quot;',
    );
    expect(html).not.toContain(' onclick="');
    expect(html.match(/<a /g)).toHaveLength(2);
    expect(emailHtml("https:// & <img src=x>")).not.toContain("<a ");
  });
});
